export default function HomeScene() {
  const ref = useRef<HTMLDivElement>(null);
  const mx = useMotionValue(0);
  const my = useMotionValue(0);
  const sx = useSpring(mx, { stiffness: 60, damping: 18 });
  const sy = useSpring(my, { stiffness: 60, damping: 18 });
  const [ready, setReady] = useState<{ mounted: boolean; isSmall: boolean }>({
    mounted: false,
    isSmall: false,
  });
  useEffect(() => {
    const mq = window.matchMedia("(max-width: 639px)");
    const update = () => setReady({ mounted: true, isSmall: mq.matches });
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  function onPointerMove(e: React.PointerEvent<HTMLDivElement>) {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    mx.set((e.clientX - rect.left) / rect.width - 0.5);
    my.set((e.clientY - rect.top) / rect.height - 0.5);
  }

  return (
    <div
      ref={ref}
      onPointerMove={onPointerMove}
      className="relative flex min-h-[calc(100svh-1px)] flex-col items-center justify-center overflow-hidden px-6 text-center"
    >
      {ready.mounted &&
        trinkets.map((t) => (
          <Piece key={t.href} trinket={t} sx={sx} sy={sy} isSmallMobile={ready.isSmall} />
        ))}

      <motion.div
        initial={{ opacity: 0, y: -16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8, ease: "easeOut" }}
        className="absolute left-1/2 top-20 z-10 -translate-x-1/2 text-center sm:top-24"
      >
        <h1 className="font-display text-[clamp(1.75rem,4.5vw,3rem)] leading-[0.95]">
          Mahsa Hosseini
        </h1>
        <p className="mt-2 text-center text-xs sm:text-sm text-ink-soft">Multidisciplinary Artist</p>
      </motion.div>
    </div>
  );
}

function Piece({
  trinket,
  sx,
  sy,
  isSmallMobile,
}: {
  trinket: Trinket;
  sx: ReturnType<typeof useSpring>;
  sy: ReturnType<typeof useSpring>;
  isSmallMobile: boolean;
}) {
  const x = useTransform(sx, (v) => v * trinket.depth);
  const y = useTransform(sy, (v) => v * trinket.depth);
  const isDesktop = useIsDesktop();
  const left = isDesktop ? trinket.leftDesktop : trinket.leftMobile;
  const top = isDesktop
    ? trinket.topDesktop
    : isSmallMobile && trinket.topSmall !== undefined
      ? trinket.topSmall
      : trinket.topMobile;
  const roamX = isDesktop ? trinket.roamXDesktop : trinket.roamXMobile;
  const roamY = isDesktop
    ? trinket.roamYDesktop
    : isSmallMobile && trinket.roamYSmall !== undefined
      ? trinket.roamYSmall
      : trinket.roamYMobile;

  return (
    <motion.div
      className={`absolute z-0 ${trinket.size}`}
      initial={{ opacity: 0, scale: 0.85, left: `${left}%`, top: `${top}%` }}
      animate={{
        opacity: 1,
        scale: 1,
        left: roamX.map((d) => `${left + d}%`),
        top: roamY.map((d) => `${top + d}%`),
      }}
      transition={{
        opacity: { duration: 0.8, delay: 0.15 },
        scale: { duration: 0.8, delay: 0.15 },
        left: { duration: trinket.floatDuration, repeat: Infinity, ease: "easeInOut", delay: 0.8 },
        top: { duration: trinket.floatDuration, repeat: Infinity, ease: "easeInOut", delay: 0.8 },
      }}
    >
      <motion.div style={{ x, y, rotate: trinket.rotate }}>
        <motion.div
          animate={{
            rotate: [0, trinket.rotate > 0 ? 16 : -16, trinket.rotate > 0 ? -10 : 10, 0],
          }}
          transition={{ duration: trinket.floatDuration, repeat: Infinity, ease: "easeInOut" }}
        >
          <Link
            href={trinket.href}
            aria-label={trinket.label}
            className="group/trinket relative block opacity-90 transition-opacity hover:opacity-100"
          >
            <motion.div
              whileHover={{ rotate: 4, scale: 1.14 }}
              transition={{ type: "spring", stiffness: 300, damping: 14 }}
              className="drop-shadow-none transition-[filter] duration-200 group-hover/trinket:drop-shadow-[0_10px_18px_rgba(1,57,97,0.3)]"
            >
              {trinket.node}
            </motion.div>
            <span className="pointer-events-none absolute left-1/2 top-full z-10 mt-2 -translate-x-1/2 translate-y-1 whitespace-nowrap rounded-full bg-[#013961] px-3 py-1 font-display text-xs text-white opacity-0 shadow-md transition-all duration-200 group-hover/trinket:translate-y-0 group-hover/trinket:opacity-100">
              {trinket.title}
            </span>
          </Link>
        </motion.div>
      </motion.div>
    </motion.div>
  );
}
